-- Generated by platform.mjs from versioned production CREATE TABLE statements.
-- Only disposable test platform services are stubbed; no email/payment network.
CREATE TABLE public.deck_templates(id uuid PRIMARY KEY);
CREATE TABLE public.deck_usage_stats (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL,
  player_tag TEXT NOT NULL,
  deck_hash TEXT NOT NULL,
  deck_cards JSONB NOT NULL,
  battles_played INTEGER DEFAULT 0,
  battles_won INTEGER DEFAULT 0,
  battles_lost INTEGER DEFAULT 0,
  total_crowns INTEGER DEFAULT 0,
  total_trophy_change INTEGER DEFAULT 0,
  avg_elixir NUMERIC,
  date DATE NOT NULL DEFAULT CURRENT_DATE,
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(user_id, deck_hash, date)
);
CREATE TABLE public.card_mastery (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL,
  player_tag TEXT NOT NULL,
  card_id INTEGER NOT NULL,
  card_name TEXT NOT NULL,
  times_used INTEGER DEFAULT 0,
  battles_won INTEGER DEFAULT 0,
  battles_lost INTEGER DEFAULT 0,
  total_crowns INTEGER DEFAULT 0,
  avg_elixir_decks NUMERIC,
  best_partner_cards TEXT[],
  worst_matchup_cards TEXT[],
  mastery_level INTEGER DEFAULT 1,
  mastery_progress INTEGER DEFAULT 0,
  ai_tips TEXT,
  last_updated TIMESTAMPTZ DEFAULT now(),
  UNIQUE(user_id, card_id)
);
CREATE TABLE public.achievements (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  description TEXT NOT NULL,
  category TEXT NOT NULL, -- 'skill', 'mastery', 'learning_path', 'milestone'
  tier TEXT NOT NULL CHECK (tier IN ('bronze', 'silver', 'gold', 'diamond', 'master')),
  icon_name TEXT NOT NULL, -- lucide icon name
  criteria JSONB NOT NULL, -- { type: 'skill_level', skill: 'cardPlacement', threshold: 5 }
  points INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE TABLE public.user_achievements (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  achievement_id UUID NOT NULL REFERENCES public.achievements(id) ON DELETE CASCADE,
  player_tag TEXT NOT NULL,
  progress INTEGER NOT NULL DEFAULT 0, -- 0-100
  unlocked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, achievement_id, player_tag)
);
CREATE TABLE public.achievement_progress (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  player_tag TEXT NOT NULL,
  skill_levels JSONB NOT NULL DEFAULT '{}'::jsonb, -- { cardPlacement: 7, timing: 6, ... }
  learning_phase TEXT NOT NULL DEFAULT 'beginner', -- 'beginner', 'intermediate', 'advanced', 'master'
  total_mastery_points INTEGER NOT NULL DEFAULT 0,
  achievements_unlocked INTEGER NOT NULL DEFAULT 0,
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(user_id, player_tag)
);
CREATE TABLE public.matchup_predictions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL,
  player_tag TEXT NOT NULL,

  -- Deck information
  deck_a_cards JSONB NOT NULL,
  deck_b_cards JSONB NOT NULL,
  deck_hash TEXT NOT NULL,

  -- Prediction data
  predicted_win_rate_a INTEGER NOT NULL,
  predicted_win_rate_b INTEGER NOT NULL,
  confidence TEXT NOT NULL CHECK (confidence IN ('high', 'medium', 'low')),
  explanation TEXT,
  key_matchups JSONB,
  tips JSONB,
  language TEXT DEFAULT 'en',

  -- Actual outcome tracking
  actual_wins_deck_a INTEGER DEFAULT 0,
  actual_losses_deck_a INTEGER DEFAULT 0,
  actual_battles_total INTEGER DEFAULT 0,

  -- Accuracy metrics
  prediction_error NUMERIC,

  -- Timestamps
  created_at TIMESTAMPTZ DEFAULT NOW(),
  last_battle_at TIMESTAMPTZ,

  -- Unique constraint for caching
  CONSTRAINT unique_deck_matchup UNIQUE (user_id, deck_hash, language)
);
CREATE TABLE public.recommendation_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL,
  player_tag TEXT NOT NULL,
  recommended_deck_id UUID REFERENCES public.deck_templates(id) ON DELETE SET NULL,
  recommended_cards JSONB,
  recommendation_reason TEXT NOT NULL,
  recommendation_score NUMERIC(4,2) NOT NULL,
  ai_explanation TEXT,
  archetype TEXT,

  -- Outcome tracking
  adopted BOOLEAN DEFAULT false,
  adopted_at TIMESTAMPTZ,
  battles_after_adoption INTEGER DEFAULT 0,
  wins_after_adoption INTEGER DEFAULT 0,
  win_rate_before NUMERIC(5,2),
  win_rate_after NUMERIC(5,2),
  outcome_tracked_at TIMESTAMPTZ,

  -- Metadata
  recommendation_type TEXT DEFAULT 'standard',
  created_at TIMESTAMPTZ DEFAULT now(),
  expires_at TIMESTAMPTZ DEFAULT (now() + INTERVAL '7 days'),

  CONSTRAINT valid_recommendation CHECK (
    (recommended_deck_id IS NOT NULL) OR (recommended_cards IS NOT NULL)
  )
);
CREATE TABLE public.api_request_logs (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id UUID,
  endpoint TEXT NOT NULL,
  query_key TEXT,
  method TEXT NOT NULL DEFAULT 'SELECT',
  duration_ms INTEGER,
  cache_hit BOOLEAN DEFAULT false,
  metadata JSONB DEFAULT '{}'::jsonb,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);
ALTER TABLE card_mastery ADD ai_tips_language text;
ALTER TABLE recommendation_history ADD COLUMN IF NOT EXISTS language text DEFAULT 'en';
ALTER TABLE profiles ADD language_selected_at timestamptz, ADD terms_accepted_at timestamptz, ADD terms_version text, ADD onboarding_completed_at timestamptz, ADD chat_retention_days integer, ADD whats_new_seen_version text, ADD acquisition_source text;
ALTER TABLE chat_messages ADD id uuid DEFAULT gen_random_uuid();
CREATE SCHEMA cron;
CREATE TABLE cron.job(jobid bigint GENERATED ALWAYS AS IDENTITY,jobname text,schedule text,command text);
CREATE FUNCTION cron.unschedule(bigint) RETURNS boolean LANGUAGE sql AS $$ DELETE FROM cron.job WHERE jobid=$1 RETURNING true $$;
CREATE FUNCTION cron.schedule(text,text,text) RETURNS bigint LANGUAGE sql AS $$ INSERT INTO cron.job(jobname,schedule,command) VALUES($1,$2,$3) RETURNING jobid $$;
